//   slot  3  0x10003000  i2c              open-ip I2C_apb

//   slot  4  0x10004000  spi              open-ip SPI_apb

//   slot  5  0x10005000  pwm              open-ip PWM_apb

//   slot  6  0x10006000  trng             open-ip TRNG_apb

//   slot  7  0x10007000  hdmi             open-ip HDMI_2_1_apb

//   slot  8  0x10008000  hdcp             open-ip HDCP_2_3_Content_Protection_apb

